                    shouldRender = true
                default:
                    break
                }
                if shouldRender {
                    let oldBaseLine: TextBaseline = canvas.textBaseline
                    let oldTextAlign: TextAlign = canvas.textAlign
                    for g in self.staves {
                        if TypeHelper.isTruthy(g.firstVisibleStaff) {
                            let firstStart: Double = cy + g.firstVisibleStaff!.contentTop
                            let lastEnd: Double = try cy + jsNonNull(g.lastVisibleStaff).contentBottom
                            var trackNameText: String = ""
                            switch trackNameMode {
                            case TrackNameMode.FullName:
                                trackNameText = g.track.name
                            case TrackNameMode.ShortName:
                                trackNameText = g.track.shortName
                            default:
                                break
                            }
                            let _trackNameStyle: (any Disposable)? = ElementStyleHelper.track(canvas, TrackSubElement.TrackName, g.track)
                            defer {
                                _trackNameStyle?.dispose()
                            }
                            if trackNameText.length > 0 {
                                let textEndX: Double = try cx + g.staves.jsElement(0).x - settings.display.accoladeBarPaddingRight - self._getInlineTuningWidthForTrackGroup(g) - (g.bracket?.width ?? 0.0) - settings.display.systemLabelPaddingRight
                                switch trackNameOrientation {
                                case TrackNameOrientation.Horizontal:
                                    canvas.textBaseline = TextBaseline.Middle
                                    canvas.textAlign = TextAlign.Right
                                    try canvas.fillText(trackNameText, textEndX, (firstStart + lastEnd) / 2.0)
                                case TrackNameOrientation.Vertical:
                                    canvas.textBaseline = TextBaseline.Bottom
                                    canvas.textAlign = TextAlign.Center
                                    let chromeTextAntialiasingFix: Double = 0.1
                                    canvas.beginRotate(textEndX, (firstStart + lastEnd) / 2.0, -90.0 - chromeTextAntialiasingFix)
                                    try canvas.fillText(trackNameText, 0.0, 0.0)
                                    canvas.endRotate()
                                default:
                                    break
                                }
                            }
                        }
                    }
                    canvas.textBaseline = oldBaseLine
                    canvas.textAlign = oldTextAlign
                }
            }
            try self._paintInlineTunings(cx, cy, canvas)
            let needsSystemBarLine: Bool = try !jsNonNull(self.layout.renderer.score).stylesheet.extendBarLines
            if self.allStaves.length > 0 && needsSystemBarLine {
                var previousStaffInBracket: RenderStaff? = nil
                for s in self.allStaves {
                    if !s.isVisible {
                        continue
                    }
                    if previousStaffInBracket != nil {
                        let previousBottom: Double = previousStaffInBracket!.contentBottom
                        let thisTop: Double = s.contentTop
                        let accoladeX: Double = cx + previousStaffInBracket!.x
                        let firstLineBarRenderer: LineBarRenderer = try jsCast(previousStaffInBracket!.barRenderers[0], LineBarRenderer.self)
                        let _using1: (any Disposable)? = ElementStyleHelper.bar(canvas, firstLineBarRenderer.staffLineBarSubElement, firstLineBarRenderer.bar)
                        defer {
                            _using1?.dispose()
                        }
                        let h: Double = Math.ceil(thisTop - previousBottom)
                        canvas.fillRect(accoladeX, cy + previousBottom, res.engravingSettings.thinBarlineThickness, h)
                    }
                    previousStaffInBracket = s
                }
            }
            try self._paintBrackets(cx, cy, canvas)
        }
    }

    private func _paintInlineTunings(_ cx: Double, _ cy: Double, _ canvas: any ICanvas) throws {
        let accoladeBarPaddingRight: Double = self.layout.renderer.settings.display.accoladeBarPaddingRight
        for glyph in self._inlineTuningGlyphs {
            let bracket: SystemBracket? = try self._staffToBracket.has(glyph.staff) ? jsNonNull(self._staffToBracket.get(glyph.staff)) : nil
            let bracketOffset: Double = TypeHelper.isTruthy(TypeHelper.isTruthy(bracket) && bracket!.width > 0) ? accoladeBarPaddingRight + bracket!.width : 0.0
            try glyph.paint(cx + glyph.staff.x - bracketOffset, cy + glyph.staff.y, canvas)
        }
    }

    private func _paintBrackets(_ cx: Double, _ cy: Double, _ canvas: any ICanvas) throws {
        let settings: Settings = self.layout.renderer.settings
        for bracket in self._brackets {
            if bracket.canPaint {
                let barStartX: Double = try cx + jsNonNull(bracket.firstVisibleStaffInBracket).x
                let barSize: Double = bracket.width
                let barOffset: Double = settings.display.accoladeBarPaddingRight
                let firstStart: Double = try cy + jsNonNull(bracket.firstVisibleStaffInBracket).contentTop
                let lastEnd: Double = try cy + jsNonNull(bracket.lastVisibleStaffInBracket).contentBottom
                var accoladeStart: Double = firstStart
                var accoladeEnd: Double = lastEnd
                if bracket.drawAsBrace {
                    try CanvasHelper.fillMusicFontSymbolSafe(canvas, barStartX - barOffset - barSize, accoladeEnd, bracket.braceScale, MusicFontSymbol.Brace)
                } else if bracket.firstVisibleStaffInBracket !== bracket.lastVisibleStaffInBracket {
                    let smuflMetrics: EngravingSettings = settings.display.resources.engravingSettings
                    let bracketOverflow: Double = smuflMetrics.oneStaffSpace * 0.25
                    accoladeStart -= bracketOverflow
                    accoladeEnd += bracketOverflow
                    let barShift: Double = 3.0
                    canvas.fillRect(barStartX - barOffset - barSize, accoladeStart - barShift, barSize, Math.ceil(accoladeEnd - accoladeStart + barShift * 2.0))
                    let spikeX: Double = barStartX - barOffset - barSize
                    try CanvasHelper.fillMusicFontSymbolSafe(canvas, spikeX, accoladeStart, 1.0, MusicFontSymbol.BracketTop)
                    try CanvasHelper.fillMusicFontSymbolSafe(canvas, spikeX, Math.floor(accoladeEnd), 1.0, MusicFontSymbol.BracketBottom)
                }
            }
        }
    }

    public func finalizeSystem() throws {
        Profiler.begin("layout.finalizeSystem")
        let settings: Settings = self.layout.renderer.settings
        if self.index == 0.0 {
            self.topPadding = settings.display.firstSystemPaddingTop
        }
        if self.isLast {
            self.bottomPadding = settings.display.lastSystemPaddingBottom
        } else if try jsNonNull(self.layout.renderer.score).stylesheet.useSystemSignSeparator && jsNonNull(self.layout.renderer.tracks).length > 1 {
            let neededHeight: Double = try jsNonNull(settings.display.resources.engravingSettings.glyphHeights.get(MusicFontSymbol.SystemDivider))
            self.bottomPadding = Math.max(self.bottomPadding, neededHeight)
            self._hasSystemSeparator = true
        }
        let anyStaffVisible: Bool = try self._finalizeTrackGroups()
        if !anyStaffVisible {
            let group: StaffTrackGroup = self.staves[0]
            let firstStaff: RenderStaff = group.staves[0]
            firstStaff.isVisible = true
            try self._finalizeTrackGroups(true)
        }
        for b in self._brackets {
            try b.finalizeBracket(settings.display.resources.engravingSettings)
        }
        try Profiler.end("layout.finalizeSystem")
    }

    /**
     * Calculates the additional vertical space needed between two adjacent staves so that
     * their content (skylines) keeps at least the given padding.
     */
    private static func _requiredStaffContentPadding(_ upper: RenderStaff, _ lower: RenderStaff, _ padding: Double, _ horizontalPadding: Double) -> Double {
        let upperSky: Skyline = upper.systemSkyline.downSky
        let lowerSky: Skyline = lower.systemSkyline.upSky
        var contentExtent: Double = 0.0
        do {
            var i: Double = 0.0
            var n: Double = upperSky.segmentCount
            while i < n {
                let h: Double = upperSky.segmentHeight(i)
                if h > 0 {
                    let combined: Double = h + lowerSky.maxHeightInRange(upperSky.segmentXStart(i) - horizontalPadding, upperSky.segmentXEnd(i) + horizontalPadding)
                    if combined > contentExtent {
                        contentExtent = combined
                    }
                }
                i += 1
            }
        }
        do {
            var i: Double = 0.0
            var n: Double = lowerSky.segmentCount
            while i < n {
                let h: Double = lowerSky.segmentHeight(i)
                if h > 0 {
                    let combined: Double = h + upperSky.maxHeightInRange(lowerSky.segmentXStart(i) - horizontalPadding, lowerSky.segmentXEnd(i) + horizontalPadding)
                    if combined > contentExtent {
                        contentExtent = combined
                    }
                }
                i += 1
            }
        }
        if contentExtent <= 0 {
            return 0.0
        }
        let available: Double = lower.contentTop - upper.contentBottom
        let missing: Double = contentExtent + padding - available
        return missing > 0 ? Math.ceil(missing) : 0.0
    }

    private func _finalizeTrackGroups(_ onlyFirstGroup: Bool = false) throws -> Bool {
        var currentY: Double = 0.0
        let settings: Settings = self.layout.renderer.settings
        let smufl: EngravingSettings = settings.display.resources.engravingSettings
        let topBracketSpikeHeight: Double = try jsNonNull(smufl.glyphHeights.get(MusicFontSymbol.BracketTop))
        let bottomBracketSpikeHeight: Double = try jsNonNull(smufl.glyphHeights.get(MusicFontSymbol.BracketBottom))
        var previousStaff: RenderStaff? = nil
        var endSpikeOverflow: Double = 0.0
        var anyStaffVisible: Bool = false
        for group in self.staves {
            var firstVisibleStaffInGroup: RenderStaff? = nil
            var lastVisibleStaffInGroup: RenderStaff? = nil
            for staff in group.staves {
                if previousStaff != nil && previousStaff!.trackIndex != staff.trackIndex {
                    currentY += settings.display.trackStaffPaddingBetween
                }
                let bracket: SystemBracket? = self._staffToBracket.has(staff) ? self._staffToBracket.get(staff) : nil
                let hasBracket: Bool? = TypeHelper.isTruthy(TypeHelper.isTruthy(bracket) && !bracket!.drawAsBrace) && bracket!.canPaint
                if TypeHelper.isTruthy(TypeHelper.isTruthy(hasBracket) && bracket!.firstStaffInBracket === staff) {
                    let spikeOverflow: Double = topBracketSpikeHeight - staff.topOverflow
                    if spikeOverflow > 0 {
                        currentY += spikeOverflow
                    }
                }
                if TypeHelper.isTruthy(TypeHelper.isTruthy(hasBracket) && bracket!.firstVisibleStaffInBracket !== bracket!.lastVisibleStaffInBracket) {
                    if bracket!.firstVisibleStaffInBracket === staff {
                        try self._registerBracketSpikeSkyline(staff, true)
                    }
                    if bracket!.lastVisibleStaffInBracket === staff {
                        try self._registerBracketSpikeSkyline(staff, false)
                    }
                }
                staff.x = self.accoladeWidth
                staff.y = currentY
                if !onlyFirstGroup {
                    try staff.finalizeStaff()
                }
                if staff.isVisible {
                    if previousStaff != nil && !onlyFirstGroup {
                        let extra: Double = StaffSystem._requiredStaffContentPadding(previousStaff!, staff, smufl.staffContentPadding, smufl.beatContentPadding)
                        if extra > 0 {
                            staff.y += extra
                            currentY += extra
                        }
                    }
                    currentY += staff.height
                    anyStaffVisible = true
                    previousStaff = staff
                    if !TypeHelper.isTruthy(firstVisibleStaffInGroup) {
                        firstVisibleStaffInGroup = staff
                    }
                    lastVisibleStaffInGroup = staff
                }
                endSpikeOverflow = 0.0
                if TypeHelper.isTruthy(TypeHelper.isTruthy(hasBracket) && bracket!.lastStaffInBracket === staff) {
                    let spikeOverflow: Double = bottomBracketSpikeHeight - staff.bottomOverflow
                    if spikeOverflow > 0 {
                        if staff.isVisible {
                            currentY += spikeOverflow
                        } else {
                            endSpikeOverflow = spikeOverflow
                        }
                    }
                }
            }
            group.firstVisibleStaff = firstVisibleStaffInGroup
            group.lastVisibleStaff = lastVisibleStaffInGroup
            if !TypeHelper.isTruthy(self.firstVisibleStaff) {
                self.firstVisibleStaff = firstVisibleStaffInGroup
            }
            if onlyFirstGroup {
                break
            }
        }
        if TypeHelper.isTruthy(endSpikeOverflow) {
            currentY += endSpikeOverflow
        }
        self._contentHeight = currentY
        return anyStaffVisible
    }

    /**
     * Registers the horizontal footprint of the bracket's top/bottom spike glyph (see
     * `_paintBrackets`'s `spikeX`) into the first bar renderer's own skyline. The spike is
     * anchored just left of the staff's content area but its glyph bbox extends `glyphWidth`
     * to the right, which can reach past the accolade into the first bar. Without this, content
     * placed at the top/bottom of that bar (e.g. the bar number) doesn't know to avoid it.
     */
    private func _registerBracketSpikeSkyline(_ staff: RenderStaff, _ isTop: Bool) throws {
        if staff.barRenderers.length == 0.0 {
            return
        }
        let settings: Settings = self.layout.renderer.settings
        let smufl: EngravingSettings = settings.display.resources.engravingSettings
        let symbol: MusicFontSymbol = isTop ? MusicFontSymbol.BracketTop : MusicFontSymbol.BracketBottom
        let glyphWidth: Double = try jsNonNull(smufl.glyphWidths.get((symbol as! MusicFontSymbol)))
        let glyphHeight: Double = try jsNonNull(smufl.glyphHeights.get((symbol as! MusicFontSymbol)))
        let barOffset: Double = settings.display.accoladeBarPaddingRight
        let intrusion: Double = glyphWidth - barOffset - smufl.bracketThickness
        if intrusion <= 0 {
            return
        }
        let height: Double = glyphHeight + smufl.oneStaffSpace * 0.25
        let firstBar: BarRendererBase = staff.barRenderers[0]
        if isTop {
            try firstBar.insertSkylineTop(0.0, intrusion, height)
        } else {
            try firstBar.insertSkylineBottom(0.0, intrusion, height)
        }
    }

    public func buildBoundingsLookup(_ cx: Double, _ cy: Double) throws {
        var paramcy = try cy
        if try jsNonNull(self.layout.renderer.boundsLookup).isFinished {
            return
        }
        let firstStaff: RenderStaff = self.allStaves[0]
        let lastStaff: RenderStaff = self.allStaves[(self.allStaves.length - 1.0).toInt()]
        paramcy += self.topPadding
        let visualTop: Double = paramcy + self.y + firstStaff.y
        let visualBottom: Double = paramcy + self.y + lastStaff.y + lastStaff.height
        let visualHeight: Double = visualBottom - visualTop
        let realTop: Double = paramcy + self.y
        let realBottom: Double = paramcy + self.y + self.height
        let realHeight: Double = realBottom - realTop
        let lineTop: Double = paramcy + self.y + firstStaff.y + firstStaff.topPadding + firstStaff.topOverflow
        let lineBottom: Double = paramcy + self.y + lastStaff.y + lastStaff.height - lastStaff.bottomPadding - lastStaff.bottomOverflow
        let lineHeight: Double = lineBottom - lineTop
        let x: Double = self.x + firstStaff.x
        let staffSystemBounds: StaffSystemBounds = StaffSystemBounds()
        staffSystemBounds.visualBounds = Bounds()
        staffSystemBounds.visualBounds.x = cx + self.x
        staffSystemBounds.visualBounds.y = paramcy + self.y
        staffSystemBounds.visualBounds.w = self.width
        staffSystemBounds.visualBounds.h = self.height - self.topPadding - self.bottomPadding
        staffSystemBounds.realBounds = Bounds()
        staffSystemBounds.realBounds.x = cx + self.x
        staffSystemBounds.realBounds.y = paramcy + self.y
        staffSystemBounds.realBounds.w = self.width
        staffSystemBounds.realBounds.h = self.height
        try jsNonNull(self.layout.renderer.boundsLookup).addStaffSystem(staffSystemBounds)
        let masterBarBoundsLookup: Map<Double, MasterBarBounds> = Map<Double, MasterBarBounds>()
        do {
            var i: Double = 0.0
            while i < self.staves.length {
                for staff in try self.staves.jsElement((i).toInt()).staves {
                    if !staff.isVisible {
                        continue
                    }
                    for renderer in staff.barRenderers {
                        var masterBarBounds: MasterBarBounds
                        if !masterBarBoundsLookup.has(renderer.bar.masterBar.index) {
                            masterBarBounds = MasterBarBounds()
                            masterBarBounds.index = renderer.bar.masterBar.index
                            masterBarBounds.isFirstOfLine = renderer.isFirstOfStaff
                            masterBarBounds.realBounds = Bounds()
                            masterBarBounds.realBounds.x = x + renderer.x
                            masterBarBounds.realBounds.y = realTop
                            masterBarBounds.realBounds.w = renderer.width
                            masterBarBounds.realBounds.h = realHeight
                            masterBarBounds.visualBounds = Bounds()
                            masterBarBounds.visualBounds.x = x + renderer.x
                            masterBarBounds.visualBounds.y = visualTop
                            masterBarBounds.visualBounds.w = renderer.width
                            masterBarBounds.visualBounds.h = visualHeight
                            masterBarBounds.lineAlignedBounds = Bounds()
                            masterBarBounds.lineAlignedBounds.x = x + renderer.x
                            masterBarBounds.lineAlignedBounds.y = lineTop
                            masterBarBounds.lineAlignedBounds.w = renderer.width
                            masterBarBounds.lineAlignedBounds.h = lineHeight
                            try jsNonNull(self.layout.renderer.boundsLookup).addMasterBar(masterBarBounds)
                            masterBarBoundsLookup.set(masterBarBounds.index, masterBarBounds)
                        } else {
                            try masterBarBounds = jsNonNull(masterBarBoundsLookup.get(renderer.bar.masterBar.index))
                        }
                        try renderer.buildBoundingsLookup(masterBarBounds, x, paramcy + self.y + staff.y)
                    }
                }
                i += 1
            }
        }
    }

    public func getBarX(_ index: Double) throws -> Double {
        if try self.allStaves.length == 0.0 || jsNonNull(self.layout.renderer.tracks).length == 0.0 {
            return 0.0
        }
        let bar: Bar = try jsNonNull(self.layout.renderer.tracks).jsElement(0).staves.jsElement(0).bars[(index).toInt()]
        let renderer: BarRendererBase = try jsNonNull(self.layout.getRendererForBar(self.allStaves.jsElement(0).staffId, bar))
        return renderer.x
    }
}

internal class SystemBracket {
    private var _system: StaffSystem!

    public var firstStaffInBracket: RenderStaff? = nil

    public var lastStaffInBracket: RenderStaff? = nil

    public var firstVisibleStaffInBracket: RenderStaff? = nil

    public var lastVisibleStaffInBracket: RenderStaff? = nil

    public var drawAsBrace: Bool = false

    public var braceScale: Double = 1.0

    public var width: Double = 0.0

    public var index: Double = 0.0

    public var canPaint: Bool = false

    private var _initialPaintabilityCaptured: Bool = false

    public var reservesAccoladeSpace: Bool = false

    public init(_ system: StaffSystem) {
        self._system = system
    }

    open func includesStaff(_ s: RenderStaff) -> Bool {
        fatalError("abstract")
    }

    public func updateCanPaint() throws {
        var firstVisibleStaff: RenderStaff? = nil
        var lastVisibleStaff: RenderStaff? = nil
        do {
            var i: Double = try jsNonNull(self.firstStaffInBracket).index
            while try i <= jsNonNull(self.lastStaffInBracket).index {
                let staff: RenderStaff = self._system.allStaves[(i).toInt()]
                if staff.isVisible {
                    if !TypeHelper.isTruthy(firstVisibleStaff) {
                        firstVisibleStaff = staff
                    }
                    lastVisibleStaff = staff
                }
                i += 1
            }
        }
        self.firstVisibleStaffInBracket = firstVisibleStaff
        self.lastVisibleStaffInBracket = lastVisibleStaff
        if !TypeHelper.isTruthy(firstVisibleStaff) || !TypeHelper.isTruthy(lastVisibleStaff) {
            self.canPaint = false
        } else {
            let singleStaffBrackets: Bool = try jsNonNull(self._system.layout.renderer.score).stylesheet.showSingleStaffBrackets
            if !singleStaffBrackets && firstVisibleStaff! === lastVisibleStaff! {
                self.canPaint = false
            } else {
                self.canPaint = true
            }
        }
        if !self._initialPaintabilityCaptured {
            self.reservesAccoladeSpace = self.canPaint
            self._initialPaintabilityCaptured = true
        }
    }

    public func finalizeBracket(_ smuflMetrics: EngravingSettings) throws {
        if !self.canPaint {
            self.width = 0.0
            return
        }
        let bravuraBraceHeightAtMusicFontSize: Double = try jsNonNull(smuflMetrics.glyphHeights.get(MusicFontSymbol.Brace))
        let bravuraBraceWidthAtMusicFontSize: Double = try jsNonNull(smuflMetrics.glyphWidths.get(MusicFontSymbol.Brace))
        if self.drawAsBrace {
            self.width = bravuraBraceWidthAtMusicFontSize
        } else {
            self.width = smuflMetrics.bracketThickness
        }
        if !self.drawAsBrace {
            return
        }
        let firstStart: Double = try jsNonNull(self.firstVisibleStaffInBracket).contentTop
        let lastEnd: Double = try jsNonNull(self.lastVisibleStaffInBracket).contentBottom
        let requiredHeight: Double = lastEnd - firstStart
        let requiredScaleForBracket: Double = requiredHeight / bravuraBraceHeightAtMusicFontSize
        self.braceScale = requiredScaleForBracket
        self.width = bravuraBraceWidthAtMusicFontSize * self.braceScale
    }
}

internal class SingleTrackSystemBracket: SystemBracket {
    internal var track: Track!

    public init(_ system: StaffSystem, _ track: Track) {
        super.init(system)
        self.track = track
        self.drawAsBrace = SingleTrackSystemBracket.isTrackDrawAsBrace(track)
    }

    public override func includesStaff(_ r: RenderStaff) -> Bool {
        return r.modelStaff.track === self.track
    }

    public static func isTrackDrawAsBrace(_ track: Track) -> Bool {
        return track.staves.filter({ (s: Staff) -> Bool in
            return (s.showStandardNotation as! Bool)
        }).length > 1
    }
}

internal final class SimilarInstrumentSystemBracket: SingleTrackSystemBracket {
    public override func includesStaff(_ r: RenderStaff) -> Bool {
        if r.modelStaff.track === self.track {
            return true
        }
        if self.drawAsBrace {
            return false
        }
        return self.track.playbackInfo.program == r.modelStaff.track.playbackInfo.program
    }

    public override init(_ system: StaffSystem, _ track: Track) {
        super.init(system, track)
    }
}
